<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import UInput from '@nuxt/ui/components/Input.vue';
import UButton from '@nuxt/ui/components/Button.vue';
import { state, date, taskStatus } from '../store';
const route = useRoute(), search = ref(''), archived = ref(false);
const fileId = computed(() => typeof route.query.fileId === 'string' ? route.query.fileId : '');
const status = ref(typeof route.query.fileState === 'string' ? route.query.fileState : '');
watch(() => [route.query.fileId,route.query.fileState], () => { search.value='';status.value=typeof route.query.fileState === 'string' ? route.query.fileState : '';archived.value=!!fileId.value; }, { immediate:true });
const tasks = computed(() => (state.board?.tasks ?? []).filter(task => (!fileId.value || task.id === fileId.value) && (!status.value || task.status === status.value) && (archived.value || !task.archived) && [task.title,task.id,task.provider].join(' ').toLowerCase().includes(search.value.toLowerCase())));
</script>
<template><section aria-labelledby="file-history-title"><h2 id="file-history-title">Retained file tasks</h2><div class="file-history-filters"><label>Find a file task<UInput v-model="search" placeholder="Title, task ID or provider" class="w-full" /></label><label class="archive-check"><input v-model="archived" type="checkbox" />Include archived tasks</label></div><p v-if="status" role="status">Showing {{ taskStatus(status) }} tasks. <button type="button" @click="status=''">Show all states</button></p><p v-if="!tasks.length" role="status">{{ fileId ? 'This retained task is unavailable in the current snapshot.' : 'No file tasks match these filters.' }}</p><ul><li v-for="task in tasks" :key="task.id"><div><strong>{{ task.title }}</strong><span>{{ taskStatus(task.status) }} · {{ date(task.createdAt) }}<template v-if="task.archived"> · archived</template></span></div><UButton color="neutral" variant="outline" :to="{ path:'/review',query:{ session:task.sessionId,fileId:task.id } }">Inspect request</UButton><RouterLink :to="{ path:'/request/maintenance',query:{ fileId:task.id } }">Manage saved task</RouterLink></li></ul></section></template>
<style scoped>h2 { font-size:1.125rem; }.file-history-filters { display:flex;align-items:end;gap:var(--space-4);flex-wrap:wrap;margin-block:var(--space-6); }.file-history-filters label { display:grid;gap:var(--space-2);font-size:.875rem;min-width:0; }.file-history-filters label:first-child { flex:1 1 260px; }.file-history-filters .archive-check { display:flex;align-items:center;min-height:44px;gap:var(--space-2); }ul { list-style:none;padding:0; }li { display:flex;align-items:center;flex-wrap:wrap;gap:var(--space-4);padding-block:var(--space-4);border-top:1px solid var(--ui-border); }li > div { flex:1 1 240px;min-width:0;overflow-wrap:anywhere; }strong,span { display:block; }span { margin-top:var(--space-2);color:var(--ui-text-muted);font-size:.8125rem; }a,button { display:inline-flex;align-items:center;min-height:44px;color:var(--ui-primary);font-size:.8125rem; }</style>
